class TaplessApp extends StatefulWidget{const TaplessApp({super.key});@override State<TaplessApp>createState()=>_TaplessAppState();}
class _TaplessAppState extends State<TaplessApp>{int tab=0;final a=<Automation>[];final runs=<RunLog>[];bool loading=true;Map<String,bool>perms={'location':false,'alarms':false,'notifications':true};@override void initState(){super.initState();load();}Future<void>load()async{final p=await SharedPreferences.getInstance();final raw=p.getString('tapless.v1');if(raw!=null){try{final d=jsonDecode(raw);a.addAll((d['automations']??[]).map<Automation>((x)=>Automation.fromJson(x)));runs.addAll((d['runs']??[]).map<RunLog>((x)=>RunLog.fromJson(x)));perms=Map<String,bool>.from(d['perms']??perms);}catch(_){}}if(a.isEmpty)a.addAll(Automation.seed());setState(()=>loading=false);}Future<void>save()async{final p=await SharedPreferences.getInstance();await p.setString('tapless.v1',jsonEncode({'automations':a.map((x)=>x.toJson()).toList(),'runs':runs.map((x)=>x.toJson()).toList(),'perms':perms}));}void execute(Automation x,{String event='Manual tap'}){final r=RunLog(x.name,DateTime.now(),x.enabled?'ran':'blocked','$event → ${x.actions.join(' → ')}');setState(()=>runs.insert(0,r));save();ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('${x.name} ${r.outcome}')));}void reset()async{final p=await SharedPreferences.getInstance();await p.remove('tapless.v1');setState((){a..clear()..addAll(Automation.seed());runs.clear();perms={'location':false,'alarms':false,'notifications':true};});}@override Widget build(BuildContext c){if(loading)return const MaterialApp(home:Scaffold(body:Center(child:CircularProgressIndicator())));return MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,scaffoldBackgroundColor:paper,colorScheme:ColorScheme.fromSeed(seedColor:pink),fontFamily:'sans'),home:Scaffold(body:SafeArea(child:IndexedStack(index:tab,children:[HomePage(a:a,onBuild:()=>builder(c),onRun:execute,onOpen:(x)=>detail(c,x)),const GalleryPage(),RunsPage(runs:runs,onOpen:(r)=>runDetail(c,r)),DoctorPage(perms:perms,onGrant:(k){setState(()=>perms[k]=true);save();}),SettingsPage(onReset:reset)])),bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.route_outlined),selectedIcon:Icon(Icons.route),label:'Gallery'),NavigationDestination(icon:Icon(Icons.train_outlined),selectedIcon:Icon(Icons.train),label:'Runs'),NavigationDestination(icon:Icon(Icons.medical_services_outlined),selectedIcon:Icon(Icons.medical_services),label:'Doctor'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'Settings')])));}void builder(BuildContext c)=>showModalBottomSheet(isScrollControlled:true,context:c,builder:(_)=>BuilderSheet(onSave:(x){setState(()=>a.insert(0,x));save();}));void detail(BuildContext c,Automation x)=>showModalBottomSheet(isScrollControlled:true,context:c,builder:(_)=>DetailSheet(a:x,onRun:()=>execute(x),onShare:()=>Share.share('Tapless recipe: ${x.name}\nhttps://tapless.example/r/${x.name.toLowerCase().replaceAll(' ','-')}')));void runDetail(BuildContext c,RunLog r)=>showModalBottomSheet(context:c,builder:(_)=>Padding(padding:const EdgeInsets.all(24),child:RunDetail(r:r)));}
class Automation{String name,trigger;List<String>conditions,actions;bool enabled;Automation(this.name,this.trigger,this.conditions,this.actions,{this.enabled=true});Map<String,dynamic>toJson()=>{'name':name,'trigger':trigger,'conditions':conditions,'actions':actions,'enabled':enabled};factory Automation.fromJson(Map x)=>Automation(x['name'],x['trigger'],List<String>.from(x['conditions']??[]),List<String>.from(x['actions']??[]),enabled:x['enabled']??true);static List<Automation>seed()=>[Automation('Car mode','Swift car connects',['Bluetooth is on'],['Open Google Maps','Play Telugu Drive','Set volume to 70%']),Automation('Bedtime','You plug in',['Between 10:30 PM and 6:00 AM'],['Do Not Disturb priority','Brightness 15%']),Automation('Morning brief','Weekdays at 7:00 AM',[],['Say today’s meetings','Show summary'])];}
class RunLog{String name,outcome,detail;DateTime at;RunLog(this.name,this.at,this.outcome,this.detail);Map<String,dynamic>toJson()=>{'name':name,'at':at.toIso8601String(),'outcome':outcome,'detail':detail};factory RunLog.fromJson(Map x)=>RunLog(x['name'],DateTime.parse(x['at']),x['outcome'],x['detail']);}
TextStyle get display=>const TextStyle(fontSize:30,fontWeight:FontWeight.w900,letterSpacing:-1.2,color:ink);TextStyle get mono=>const TextStyle(fontSize:11,letterSpacing:1.2,color:Color(0xff655d74));Widget pill(String t,{Color c=ink,Color bg=const Color(0xfff2e9ee)})=>Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:6),decoration:BoxDecoration(color:bg,borderRadius:BorderRadius.circular(99)),child:Text(t,style:TextStyle(color:c,fontSize:12,fontWeight:FontWeight.w700)));Widget station(IconData i)=>Container(width:24,height:24,decoration:const BoxDecoration(shape:BoxShape.circle,color:ink),child:Icon(i,size:13,color:Colors.white));
