uild.',style:TextStyle(color:Color(0xff655d74),fontSize:12))]);}
class BuilderSheet extends StatefulWidget{final void Function(Automation)onSave;const BuilderSheet({super.key,required this.onSave});@override State<BuilderSheet>createState()=>_BuilderSheetState();}class _BuilderSheetState extends State<BuilderSheet>{final t=TextEditingController();String?status;Automation?draft;String?place,playlist;void compile(){final s=t.text.toLowerCase();setState((){status=s.contains('gym')?'Recipe matched · no AI call':'AI compile (simulated)';draft=s.contains('gym')?Automation('Gym mode','Arrive at a place',['Between 5:30 AM and 10:00 AM','Mon to Sat'],['Do Not Disturb priority','Play ${playlist??'{playlist}'}','Quiet notification']):Automation('My automation','When you tap it',[],[s.contains('silent')?'Set ringer silent':'Run the requested action']);});}@override Widget build(BuildContext c)=>Padding(padding:EdgeInsets.only(bottom:MediaQuery.of(c).viewInsets.bottom),child:DraggableScrollableSheet(expand:false,initialChildSize:.86,builder:(_,sc)=>Material(child:ListView(controller:sc,padding:const EdgeInsets.all(20),children:[Text('Say it like you’d text a friend.',style:display),const SizedBox(height:14),TextField(controller:t,maxLines:3,decoration:const InputDecoration(hintText:'When I get to the gym, silence my phone…',filled:true)),const SizedBox(height:10),FilledButton.icon(onPressed:compile,icon:const Icon(Icons.auto_awesome),label:const Text('Build')),if(status!=null)Padding(padding:const EdgeInsets.symmetric(vertical:12),child:Text(status!,style:mono)),if(draft!=null)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(draft!.name,style:const TextStyle(fontWeight:FontWeight.w800,fontSize:22,color:ink)),Text('WHEN  ${draft!.trigger}'),...draft!.conditions.map((x)=>Text('ONLY IF  $x')),const Divider(),Text('DO',style:mono),...draft!.actions.map((x)=>Text('●  $x')),if(draft!.name=='Gym mode')... [const SizedBox(height:12),const Text('Which gym?'),Wrap(spacing:8,children:['Cult.fit Kondapur','Gold’s Gym Jubilee Hills'].map((x)=>ChoiceChip(label:Text(x),selected:place==x,onSelected:(_){setState(()=>place=x);})).toList()),const Text('Which playlist?'),Wrap(spacing:8,children:['Gym Bangers','Telugu Drive','Liked Songs'].map((x)=>ChoiceChip(label:Text(x),selected:playlist==x,onSelected:(_){setState(()=>playlist=x);})).toList())]))),const SizedBox(height:12),FilledButton(onPressed:draft==null||draft!.name=='Gym mode'&&(place==null||playlist==null)?null:(){widget.onSave(draft!);Navigator.pop(c);},child:const Text('Save to Tapless'))]))));}}
class DetailSheet extends StatelessWidget{final Automation a;final VoidCallback onRun,onShare;const DetailSheet({super.key,required this.a,required this.onRun,required this.onShare});@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.all(20),child:DraggableScrollableSheet(expand:false,initialChildSize:.7,builder:(_,sc)=>ListView(controller:sc,children:[Text(a.name,style:display),Text(a.trigger,style:const TextStyle(fontSize:16,color:Color(0xff655d74))),const SizedBox(height:20),...a.conditions.map((x)=>ListTile(leading:const Icon(Icons.crop_square,color:bronze),title:Text(x))),...a.actions.map((x)=>ListTile(leading:const Icon(Icons.circle,color:ink),title:Text(x))),FilledButton.icon(onPressed:onRun,icon:const Icon(Icons.play_arrow),label:const Text('Test run')),OutlinedButton.icon(onPressed:onShare,icon:const Icon(Icons.share),label:const Text('Share recipe'))])));}
